import React from "react";
import { MapPin, Star, ArrowRight } from "lucide-react";
import Background from "../components/Background";
import "../styles/Marketplace.css";

const projectsData = [
  {
    id: 1,
    name: "Vinhomes Grand Park – TPHCM",
    type: "Căn hộ cao cấp",
    hot: true,
    location: "Quận 9, TP. Hồ Chí Minh",
    rating: 4.9,
    reviews: 156,
    tags: ["Thông minh", "Sông xanh", "Tiện ích 5 sao"],
    thumbnail: "/images/vinhomes.png",
  },
  {
    id: 2,
    name: "FLC Quy Nhon Beach & Golf Resort",
    type: "Resort nghỉ dưỡng",
    hot: true,
    location: "Quy Nhơn, Bình Định",
    rating: 4.7,
    reviews: 89,
    tags: ["Biển", "Golf", "Nghỉ dưỡng"],
    thumbnail: "/images/flc.png",
  },
  {
    id: 3,
    name: "Dalat Wonder Resort",
    type: "Resort sinh thái",
    hot: false,
    location: "Đà Lạt, Lâm Đồng",
    rating: 4.8,
    reviews: 124,
    tags: ["Sinh thái", "Hồ Tuyền Lâm", "Tự nhiên"],
    thumbnail: "/images/dalat.png",
  },
];

const Marketplace = () => {
  return (
    <Background showShapes={false} fullWidth={true}>
      <div className="marketplace-page">
        {/* Hero */}
        <section className="marketplace-hero">
          <h1>Khám phá những Dự Án Bất Động Sản Nổi Bật</h1>
          <p>
            Tìm kiếm cơ hội đầu tư, không gian sống và nghỉ dưỡng đẳng cấp —
            tổng hợp các dự án nổi bật được chọn lọc bởi <strong>LandingHub</strong>.
          </p>
          <a href="#projects" className="hero-cta">
            Khám phá ngay <ArrowRight size={18} />
          </a>
        </section>

        {/* Projects Grid */}
        <section id="projects" className="projects-section">
          <div className="projects-grid">
            {projectsData.map((project) => (
              <div key={project.id} className="project-card fade-in">
                <div className="thumbnail-wrapper">
                  <img
                    src={project.thumbnail}
                    alt={project.name}
                    className="thumbnail"
                  />
                  <div className="overlay">
                    <span className="badge">{project.type}</span>
                    {project.hot && <span className="hot">🔥 Hot</span>}
                  </div>
                </div>

                <div className="project-info">
                  <h2 className="project-name">{project.name}</h2>

                  <div className="location">
                    <MapPin size={16} /> {project.location}
                  </div>

                  <div className="rating">
                    <Star size={16} color="#facc15" />{" "}
                    {project.rating}{" "}
                    <span className="reviews">
                      ({project.reviews} đánh giá)
                    </span>
                  </div>

                  <div className="tags">
                    {project.tags.map((tag, index) => (
                      <span key={index} className="tag">
                        {tag}
                      </span>
                    ))}
                  </div>

                  <div className="actions">
                    <button className="btn-outline">Xem trước</button>
                    <button className="btn-primary">Chi tiết</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>
    </Background>
  );
};

export default Marketplace;
